globex_prompt = mw._prepare_for_call(SimpleNamespace(tools=[lookup_tool('Search globex issues.')], state=globex))
swapped = mw._prepare_for_call(SimpleNamespace(tools=[lookup_tool('Search acme pull requests.')], state=acme))
