'Every `${{ }}` call must name a function GitHub Actions actually has.\n\n    An unknown name (`toLower`, `replace`, `split`, `sort` — all real in other\n    CI dialects) is rejected at workflow load, so the file never runs at all:\n    no job, no `if: failure()`, no tracking issue. YAML-parsing the file cannot\n    catch it, because an invalid expression is still valid YAML.\n    '
known = {'contains', 'startswith', 'endswith', 'format', 'join', 'tojson', 'fromjson', 'hashfiles', 'success', 'always', 'cancelled', 'failure'}
for workflow in sorted((REPO_ROOT / '.github' / 'workflows').glob('*.yml')):
    text = workflow.read_text(encoding='utf-8')
    for expression in re.findall('\\$\\{\\{(.*?)\\}\\}', text, re.DOTALL):
        called = set(re.findall('([A-Za-z_][A-Za-z0-9_]*)\\s*\\(', expression))
        unknown = {name for name in called if name.lower() not in known}
        assert not unknown, f'{workflow.name}: unknown expression function(s) {unknown}'

