'A failed lock-token write aborts loudly and removes the half-made lock.

    After winning `mkdir`, the metadata write must succeed or the acquire has to
    `exit 1` and clean up. Here a stubbed `mkdir` plants a *directory* named
    `token` inside the fresh lock so `>"$INSTALL_LOCK_DIR/token"` fails. Guards
    against a regression that drops either the cleanup (orphan lock nobody can
    release) or the `exit` (install proceeds tokenless, so release never matches
    and the lock leaks permanently).
    '
installation_root = tmp_path / 'tools' / 'deepagents-code'
lock_root = tmp_path / '.tools.deepagents-code.deepagents-code-locks'
lock_root.mkdir(parents=True)
script = tmp_path / 'token_write_harness.sh'
script.write_text(f"""HOME={str(tmp_path)!r}
INSTALL_LOCK_KIND=''
INSTALL_LOCK_DIR=''
INSTALL_LOCK_RECLAIM_DIR=''
INSTALL_LOCK_RECLAIM_TOKEN=''
INSTALL_LOCK_STALE_AFTER_SECS=600
fix_file_owner() {{ return 0; }}
resolve_installation_root() {{ printf '%s' {str(installation_root)!r}; }}
log_warn() {{ return 0; }}
log_error() {{ printf '%s\n' "$*" >&2; }}
{_extract_shell_function('lock_dir_mtime')}
{_extract_shell_function('install_lock_identity')}
{_extract_shell_function('install_lock_is_stale')}
{_extract_shell_function('install_lock_reclaim_guard_is_stale')}
{_extract_shell_function('wait_for_install_lock_reclaim_guard')}
{_extract_shell_function('acquire_install_lock_reclaim_guard')}
{_extract_shell_function('release_install_lock_reclaim_guard')}
{_extract_shell_function('acquire_install_lock_root')}
{_extract_shell_function('acquire_install_lock')}
mkdir() {{
  if [ "$1" = "$INSTALL_LOCK_DIR" ]; then
    command mkdir "$INSTALL_LOCK_DIR" || return 1
    command mkdir "$INSTALL_LOCK_DIR/token"
    return 0
  fi
  command mkdir "$@"
}}
acquire_install_lock
""", encoding='utf-8')
